func (this *MassiveCore) fetchOrderBookBody(ch chan any, symbol any, optionalArgs ...any) any {
    defer close(ch)
    defer ReturnPanicError(ch)
        limit := GetArg(optionalArgs, 0, nil)
        _ = limit
        params := GetArg(optionalArgs, 1, map[string]any {})
        _ = params
    
        retRes8048 := (<-this.LoadMarkets())
        PanicOnError(retRes8048)
        var market any = this.Market(symbol)
        var request map[string]any = map[string]any {
            "stocksTicker": GetValue(market, "id"),
        }
    
        response:= (<-this.PublicGetV2LastNbboStocksTicker(this.Extend(request, params)))
        PanicOnError(response)
        //
        //     {
        //         "request_id": "b84e24636301f19f88e0dfbf9a45ed5c",
        //         "status": "OK",
        //         "results": {
        //             "P": 127.98,
        //             "S": 7,
        //             "T": "AAPL",
        //             "X": 19,
        //             "p": 127.96,
        //             "q": 83480742,
        //             "s": 1,
        //             "t": 1617827221349730300,
        //             "x": 11,
        //             "y": 1617827221349366000,
        //             "z": 3
        //         }
        //     }
        //
        var result any = this.SafeDict(response, "results", map[string]any {})
        var timestamp any = this.SafeIntegerProduct(result, "t", 0.000001)
        var bids any = []any{}
        var asks any = []any{}
        var bidPrice any = this.SafeString(result, "p")
        var bidAmount any = this.SafeString(result, "s")
        if IsTrue(IsTrue((!IsEqual(bidPrice, nil))) && IsTrue(Precise.StringGt(bidPrice, "0"))) {
            AppendToArray(&bids, []any{bidPrice, bidAmount})
        }
        var askPrice any = this.SafeString(result, "P")
        var askAmount any = this.SafeString(result, "S")
        if IsTrue(IsTrue((!IsEqual(askPrice, nil))) && IsTrue(Precise.StringGt(askPrice, "0"))) {
            AppendToArray(&asks, []any{askPrice, askAmount})
        }
        var rawOrderBook map[string]any = map[string]any {
            "bids": bids,
            "asks": asks,
        }
        var orderbook any = this.ParseOrderBook(rawOrderBook, GetValue(market, "symbol"), timestamp)
        AddElementToObject(orderbook, "nonce", this.SafeInteger(result, "q"))
    
        ch <- orderbook
        return nil
}
func  (this *MassiveCore) Sign(path any, optionalArgs ...any) any  {
    // every massive endpoint is authenticated, the api key entitles the
    // caller to a data feed, it is not bound to a trading account
    api := GetArg(optionalArgs, 0, "public")
    _ = api
    method := GetArg(optionalArgs, 1, "GET")
    _ = method
    params := GetArg(optionalArgs, 2, map[string]any {})
    _ = params
    headers := GetArg(optionalArgs, 3, nil)
    _ = headers
    body := GetArg(optionalArgs, 4, nil)
    _ = body
    this.CheckRequiredCredentials()
    var request any = Add("/", this.ImplodeParams(path, params))
    var url any = Add(this.ImplodeHostname(GetValue(GetValue(this.Urls, "api"), "public")), request)
    var query any = this.Omit(params, this.ExtractParams(path))
    var queryLength int =     GetArrayLength(ObjectKeys(query))
    if IsTrue(IsGreaterThan(queryLength, 0)) {
        url = Add(url, Add("?", this.Urlencode(query)))
    }
    headers = map[string]any {
        "Authorization": Add("Bearer ", this.ApiKey),
        "Accept": "application/json",
    }
    return map[string]any {
        "url": url,
        "method": method,
        "body": body,
        "headers": headers,
    }
}
func  (this *MassiveCore) HandleErrors(code any, reason any, url any, method any, headers any, body any, response any, requestHeaders any, requestBody any) any  {
    if IsTrue(IsEqual(response, nil)) {
        return nil  // fallback to the default error handler
    }
    var status any = this.SafeString(response, "status")
    // DELAYED is a successful response on the delayed data plans
    if IsTrue(IsTrue((IsEqual(status, "OK"))) || IsTrue((IsEqual(status, "DELAYED")))) {
        return nil
    }
    var error any = this.SafeString2(response, "error", "message")
    if IsTrue(IsTrue((IsEqual(status, nil))) && IsTrue((IsEqual(error, nil)))) {
        return nil
    }
    //
    //     { "status": "NOT_AUTHORIZED", "request_id": "943c", "message": "You are not entitled to this data." }
    //     { "status": "ERROR", "request_id": "943c", "error": "Unknown API Key" }
    //
    var feedback any = Add(Add(this.Id, " "), body)
    this.ThrowExactlyMatchedException(GetValue(this.Exceptions, "exact"), error, feedback)
    this.ThrowBroadlyMatchedException(GetValue(this.Exceptions, "broad"), error, feedback)
    this.ThrowExactlyMatchedException(GetValue(this.Exceptions, "exact"), status, feedback)
    panic(ExchangeError(feedback))
}


func (this *MassiveCore) Init(userConfig map[string]any) {
    this.Exchange = Exchange{}
    this.Exchange.DerivedExchange = this
    this.Exchange.InitParent(userConfig, this.Describe().(map[string]any), this)
}
